#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> logs(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> logs[i][j];
        }
    }

    parent.resize(n + 1);
    sizes.assign(n + 1, 1);
    for (int v = 0; v <= n; v++) parent[v] = v;
    sort(logs.begin(), logs.end());
    long long groups = n, answer = -1;
    for (const vector<long long>& entry : logs) {
        if (unite((int)entry[1], (int)entry[2])) {
            groups--;
            if (groups == 1) {
                answer = entry[0];
                break;
            }
        }
    }
    cout << answer << "\n";

    return 0;
}

