import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;
    static int[] sizes;

    static int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static boolean unite(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return false;
        if (sizes[a] < sizes[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sizes[a] += sizes[b];
        return true;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] logs = new long[(int) m][3];
        for (int i = 0; i < logs.length; i++) {
            for (int j = 0; j < logs[i].length; j++) {
                logs[i][j] = Long.parseLong(next());
            }
        }

        int people = (int) n;
        parent = new int[people + 1];
        sizes = new int[people + 1];
        for (int v = 0; v <= people; v++) {
            parent[v] = v;
            sizes[v] = 1;
        }
        Arrays.sort(logs, (x, y) -> Long.compare(x[0], y[0]));
        long groups = n, answer = -1;
        for (long[] entry : logs) {
            if (unite((int) entry[1], (int) entry[2])) {
                groups--;
                if (groups == 1) {
                    answer = entry[0];
                    break;
                }
            }
        }
        System.out.println(answer);
    }
}
